do $$ declare p record; begin
 for p in select policyname,tablename from pg_policies where schemaname='public' and tablename in ('pastoral_requests','pastoral_followups') loop execute format('drop policy %I on public.%I',p.policyname,p.tablename); end loop;
end $$;
create policy pastoral_requests_permission_select on public.pastoral_requests for select to authenticated using (private.has_church_permission(church_id,'pastoral','view') or exists(select 1 from public.church_members cm where cm.church_id=pastoral_requests.church_id and cm.user_id=auth.uid() and cm.status='active' and pastoral_requests.assigned_pastor_user_id=auth.uid()));
create policy pastoral_requests_permission_insert on public.pastoral_requests for insert to authenticated with check (private.has_church_permission(church_id,'pastoral','create'));
create policy pastoral_requests_permission_update on public.pastoral_requests for update to authenticated using (private.has_church_permission(church_id,'pastoral','edit') or exists(select 1 from public.church_members cm where cm.church_id=pastoral_requests.church_id and cm.user_id=auth.uid() and cm.status='active' and pastoral_requests.assigned_pastor_user_id=auth.uid())) with check (private.has_church_permission(church_id,'pastoral','edit') or exists(select 1 from public.church_members cm where cm.church_id=pastoral_requests.church_id and cm.user_id=auth.uid() and cm.status='active' and pastoral_requests.assigned_pastor_user_id=auth.uid()));
create policy pastoral_requests_permission_delete on public.pastoral_requests for delete to authenticated using (private.has_church_permission(church_id,'pastoral','delete'));
create policy pastoral_followups_permission_select on public.pastoral_followups for select to authenticated using (private.has_church_permission(church_id,'pastoral','view') or exists(select 1 from public.pastoral_requests pr join public.church_members cm on cm.church_id=pr.church_id and cm.user_id=auth.uid() and cm.status='active' where pr.id=pastoral_followups.request_id and pr.church_id=pastoral_followups.church_id and pr.assigned_pastor_user_id=auth.uid()));
create policy pastoral_followups_permission_insert on public.pastoral_followups for insert to authenticated with check (private.has_church_permission(church_id,'pastoral','create'));
create policy pastoral_followups_permission_update on public.pastoral_followups for update to authenticated using (private.has_church_permission(church_id,'pastoral','edit') or exists(select 1 from public.pastoral_requests pr join public.church_members cm on cm.church_id=pr.church_id and cm.user_id=auth.uid() and cm.status='active' where pr.id=pastoral_followups.request_id and pr.church_id=pastoral_followups.church_id and pr.assigned_pastor_user_id=auth.uid())) with check (private.has_church_permission(church_id,'pastoral','edit') or exists(select 1 from public.pastoral_requests pr join public.church_members cm on cm.church_id=pr.church_id and cm.user_id=auth.uid() and cm.status='active' where pr.id=pastoral_followups.request_id and pr.church_id=pastoral_followups.church_id and pr.assigned_pastor_user_id=auth.uid()));
create policy pastoral_followups_permission_delete on public.pastoral_followups for delete to authenticated using (private.has_church_permission(church_id,'pastoral','delete'));
